import{_ as s,o as a,c as n,ag as i}from"./chunks/framework.C9sp7nFj.js";const k=JSON.parse('{"title":"Concepts","description":"","frontmatter":{},"headers":[],"relativePath":"guide/concepts.md","filePath":"guide/concepts.md","lastUpdated":1779875348000}'),t={name:"guide/concepts.md"};function o(r,e,l,h,p,d){return a(),n("div",null,[...e[0]||(e[0]=[i(`<h1 id="concepts" tabindex="-1">Concepts <a class="header-anchor" href="#concepts" aria-label="Permalink to &quot;Concepts&quot;">​</a></h1><p>A few short definitions before the rest of the guide makes sense.</p><h2 id="folders-and-files" tabindex="-1">Folders and files <a class="header-anchor" href="#folders-and-files" aria-label="Permalink to &quot;Folders and files&quot;">​</a></h2><p>The config store is a tree. Internal nodes are <strong>folders</strong>; leaves are <strong>config files</strong>. Paths use forward slashes:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>myapp/</span></span>
<span class="line"><span>├── config         (file — JSON)</span></span>
<span class="line"><span>├── secrets        (file — YAML)</span></span>
<span class="line"><span>└── workers/</span></span>
<span class="line"><span>    ├── config     (file — TOML)</span></span>
<span class="line"><span>    └── secrets    (file — YAML)</span></span></code></pre></div><p>A path like <code>myapp/workers/config</code> uniquely identifies a file. The same path is what consumers use against <code>/data/myapp/workers/config</code>.</p><p>Folders are created implicitly when you save a file inside them.</p><h2 id="files" tabindex="-1">Files <a class="header-anchor" href="#files" aria-label="Permalink to &quot;Files&quot;">​</a></h2><p>A <strong>file</strong> is a single content blob with:</p><ul><li>a <strong>format</strong> (<code>json</code>, <code>yaml</code>, or <code>toml</code>) that determines storage and validation,</li><li>a <strong>version history</strong> — every save creates a new version,</li><li>zero or more <strong>variants</strong> — independent copies of the file for different environments,</li><li>zero or more <strong>inheritance entries</strong> — references to other configs or external sources that get merged in at read time.</li></ul><p>Files behave like documents, not like key-value pairs. You edit the whole document, get back the whole document.</p><h2 id="versions" tabindex="-1">Versions <a class="header-anchor" href="#versions" aria-label="Permalink to &quot;Versions&quot;">​</a></h2><p>Every save bumps the version number (<code>1</code>, <code>2</code>, <code>3</code>, …). Old versions are kept and can be fetched directly:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -H</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Authorization: Bearer </span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$TOKEN</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  http://localhost:8080/data/myapp/config?version=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">3</span></span></code></pre></div><p>Versions can also be <strong>tagged with a semver constraint</strong> (e.g. <code>&gt;= 0.1.0</code>) so consumers can request a config that matches their own application version. See <a href="./versions-variants">Versions &amp; variants</a> for the details.</p><h2 id="variants" tabindex="-1">Variants <a class="header-anchor" href="#variants" aria-label="Permalink to &quot;Variants&quot;">​</a></h2><p>A <strong>variant</strong> is a parallel version history of the same file scoped to a specific name — <code>prod</code>, <code>staging</code>, <code>dev</code>, or anything you choose. Variants share the path but not the content. They&#39;re stored internally as <code>path@variant</code>.</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Base</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">GET</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /data/myapp/config</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Production variant</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">GET</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /data/myapp/config?variant=prod</span></span></code></pre></div><p>Each variant has its own version history and can have its own inheritance chain.</p><h2 id="inheritance" tabindex="-1">Inheritance <a class="header-anchor" href="#inheritance" aria-label="Permalink to &quot;Inheritance&quot;">​</a></h2><p>Files can declare <strong>inheritance entries</strong> that pull data from elsewhere and merge it into the resolved output. Sources include:</p><ul><li>another pika file (or one of its variants),</li><li>an <a href="./inheritance/">external resource</a> (Vault, Kubernetes, Consul, etcd, AWS, GCP, Azure, plain HTTP).</li></ul><p>Merging happens at <strong>read time</strong>, not at save time. The stored file content is always your hand-edited document; pika resolves the inheritance chain when a consumer asks for it.</p><h2 id="tokens-and-scopes" tabindex="-1">Tokens and scopes <a class="header-anchor" href="#tokens-and-scopes" aria-label="Permalink to &quot;Tokens and scopes&quot;">​</a></h2><p>API tokens authenticate non-human consumers. Each token has 1+ <strong>scopes</strong>, where a scope is a <code>path</code> glob plus a list of allowed operations (<code>read</code>, <code>write</code>, <code>delete</code>).</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;path&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;myapp/**&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;operations&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;read&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>See <a href="/reference/tokens-and-scopes">Tokens &amp; scopes</a> for the matcher rules.</p><h2 id="hooks" tabindex="-1">Hooks <a class="header-anchor" href="#hooks" aria-label="Permalink to &quot;Hooks&quot;">​</a></h2><p>A <strong>hook</strong> is a subscription to events. When a file or config changes, pika dispatches a JSON event to one or more <strong>targets</strong> (HTTP webhook, Kafka, Redis Pub/Sub, NATS, log). See <a href="./hooks">Hooks</a>.</p><h2 id="settings" tabindex="-1">Settings <a class="header-anchor" href="#settings" aria-label="Permalink to &quot;Settings&quot;">​</a></h2><p>Almost everything beyond ports and storage paths is stored in the database and edited from the UI under <strong>Settings</strong>. That includes auth strategies, external resources, hooks, and user-sync schedules. The settings document itself is fetched and patched via <code>GET</code>/<code>POST /api/v1/settings</code>.</p>`,31)])])}const g=s(t,[["render",o]]);export{k as __pageData,g as default};
